(function() {
  var SRC_B64="";
  var u = new Uint8Array(atob(SRC_B64).length);
  for(var i=0; i<u.length; i++) u[i] = atob(SRC_B64).charCodeAt(i);
  var html = new TextDecoder('utf-8').decode(u);
  
  var ifr = document.getElementById('ifr');
  if(!ifr) return;
  
  var cam = document.getElementById('cam');
  var hl = document.getElementById('hl');
  var rip = document.getElementById('rip');
  var cur = document.getElementById('cur');
  var cur2 = document.getElementById('cur2');
  var veil = document.getElementById('veil');
  var wrap = document.getElementById('wrap');
  var SPD = 1.14;
  var sleep = function(ms) { return new Promise(function(r){setTimeout(r, ms/SPD)}); };
  var rsleep = function(ms) { return new Promise(function(r){setTimeout(r, ms)}); };
  
  var C={x:720,y:450,s:1}, T={x:730,y:452,s:1.03}, V={x:0,y:0,s:0}, ST=1.2, lastT=performance.now();
  function sd(c,t,v,st,dt){var o=2/st,x=o*dt,e=1/(1+x+.48*x*x+.235*x*x*x),ch=c-t,tmp=(v+o*ch)*dt;return[t+(ch+tmp)*e,(v-o*tmp)*e]}
  function clampT(){var hw=720/T.s,hh=450/T.s;T.x=Math.min(1440-hw,Math.max(hw,T.x));T.y=Math.min(900-hh,Math.max(hh,T.y))}
  var lastStr='';
  function frame(now){
    var dt=Math.min(.05,(now-lastT)/1000);lastT=now;
    var r;
    r=sd(Math.log(C.s),Math.log(T.s),V.s,ST,dt);C.s=Math.exp(r[0]);V.s=r[1];
    r=sd(C.x,T.x,V.x,ST*.95,dt);C.x=r[0];V.x=r[1];
    r=sd(C.y,T.y,V.y,ST*.95,dt);C.y=r[0];V.y=r[1];
    var k=wrap.clientWidth/1440,dx=Math.sin(now/2600)*3,dy=Math.cos(now/3100)*2,sc=k*C.s;
    var s='translate3d('+((wrap.clientWidth/2-(C.x+dx)*sc)).toFixed(2)+'px,'+((wrap.clientHeight/2-(C.y+dy)*sc)).toFixed(2)+'px,0) scale('+sc.toFixed(4)+')';
    if(s!==lastStr){cam.style.transform=s;lastStr=s}
    drawCur(now);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
  function camTo(x,y,s,dval){T.x=x;T.y=y;T.s=s;clampT();ST=Math.max(.34,(dval||1200)/SPD/1000*.38)}
  function focus(cx,cy,vw,vh,dval,cap){
    var s=Math.min(1440*.5/vw,900*.44/vh,(cap||2.1)*.86);s=Math.max(1.22,s);camTo(cx,cy,s,dval||1100);
  }
  function wide(dval){camTo(720,450,1,dval||1300)}
  var P={x:1500,y:260}, hist=[];
  function drawCur(now){
    var z=1/Math.pow(C.s,.7),sp=0;
    if(hist.length>1){var a=hist[0],b=hist[hist.length-1];sp=Math.hypot(b.x-a.x,b.y-a.y)/Math.max(16,b.t-a.t)}
    cur.style.transform='translate3d('+P.x.toFixed(1)+'px,'+P.y.toFixed(1)+'px,0) scale('+z.toFixed(3)+')';
    var g=hist.length?hist[0]:P;
    cur2.style.transform='translate3d('+g.x.toFixed(1)+'px,'+g.y.toFixed(1)+'px,0) scale('+z.toFixed(3)+')';
    cur2.style.opacity=(+cur.style.opacity>0)?Math.min(.18,Math.max(0,(sp-.7)*.14)):0;
    while(hist.length&&now-hist[0].t>60)hist.shift();
    hist.push({x:P.x,y:P.y,t:now});
  }
  var eio=function(t){return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2};
  var eoq=function(t){return 1-Math.pow(1-t,4)};
  function moveTo(x,y,dval){
    dval=dval/SPD;return new Promise(function(res){
      var x0=P.x,y0=P.y,dx=x-x0,dy=y-y0,dist=Math.hypot(dx,dy)||1,o=Math.min(50,dist*.1),
          bx=x0+dx/2-dy/dist*o,by=y0+dy/2+dx/dist*o,t0=performance.now();
      (function f(n){
        var p=Math.min(1,(n-t0)/dval),e=eio(p)*.3+eoq(p)*.7,u=1-e;
        P.x=u*u*x0+2*u*e*bx+e*e*x;P.y=u*u*y0+2*u*e*by+e*e*y;
        if(p<1)requestAnimationFrame(f);else{P.x=x;P.y=y;res()}
      })(t0);
    });
  }
  function R(el){var r=el.getBoundingClientRect();return{l:r.left,t:r.top,w:r.width,h:r.height,cx:r.left+r.width/2,cy:r.top+r.height/2}}
  async function waitFor(fn,to){var t0=Date.now();while(Date.now()-t0<(to||4000)){var v=fn();if(v)return v;await sleep(50)}return null}
  var lifted=null;
  function unlift(){if(lifted){lifted.style.transform=lifted._t||'';lifted.style.boxShadow=lifted._b||'';lifted=null}}
  function lift(el){unlift();if(/^(TR|TD|TH|TABLE)$/.test(el.tagName)||el.classList.contains('ship-drawer'))return;
    el._t=el.style.transform;el._b=el.style.boxShadow;
    el.style.transition='transform .35s cubic-bezier(.2,.7,.2,1),box-shadow .35s ease,background .2s';
    el.style.transform='translateY(-1px) scale(1.025)';el.style.boxShadow='0 8px 20px rgba(0,0,0,.2)';lifted=el}
  function glow(el,tone,pad){var r=R(el);pad=pad==null?3:pad;hl.className=tone;
    hl.style.left=(r.l-pad)+'px';hl.style.top=(r.t-pad)+'px';hl.style.width=(r.w+pad*2)+'px';hl.style.height=(r.h+pad*2)+'px';hl.style.opacity=1;lift(el)}
  function unglow(){hl.style.opacity=0;unlift()}
  async function click(el){
    cur.classList.add('press');await sleep(70);
    rip.style.left=P.x+'px';rip.style.top=P.y+'px';rip.classList.remove('go');void rip.offsetWidth;rip.classList.add('go');
    el.click();await sleep(90);cur.classList.remove('press');
  }
  function byText(root,sel,txt){var l=root.querySelectorAll(sel);for(var i=0;i<l.length;i++){if(l[i].textContent.trim().toLowerCase().indexOf(txt)===0)return l[i]}return null}
  async function aimAt(el,tone,dur,ox,oy,pad){var r=R(el);await moveTo(r.cx+(ox||0),r.cy+(oy||0),dur);glow(el,tone,pad)}
  function veilOn(on,lv){veil.style.opacity=on?(lv||.4):0}
  function showHero(tt,s,m){var h=document.getElementById('hero');h.className='m-'+m;document.getElementById('hT').innerHTML=tt;document.getElementById('hS').textContent=s||'';void h.offsetWidth;h.classList.add('on')}
  function heroVeil(on){document.getElementById('veil2').style.opacity=on?.94:0}
  function hideHero(){document.getElementById('hero').classList.remove('on')}
  var capEl=document.getElementById('cap'),capBusy=0;
  async function setCap(title,sub,step,big){
    var id=++capBusy;capEl.classList.remove('on');capEl.classList.add('out');await sleep(260);if(id!==capBusy)return;
    document.getElementById('capT').textContent=title;
    document.getElementById('capL').textContent=step?('Step '+step+' of 3'):'';
    document.getElementById('capL').style.display=step?'':'none';
    document.getElementById('capS').textContent=sub||'';
    document.getElementById('capS').style.display=sub?'':'none';
    capEl.classList.toggle('nodots',!step);capEl.classList.toggle('big',!!big);
    var dots=capEl.querySelectorAll('.cdots i');for(var i=0;i<3;i++)dots[i].classList.toggle('a',step>0&&i<step);
    capEl.classList.remove('out');void capEl.offsetWidth;capEl.classList.add('on');
  }
  function hideCap(){capBusy++;capEl.classList.remove('on');capEl.classList.add('out')}
  function fitEl(el,dval,cap){var r=R(el),s=Math.min((cap||1.7)*.9,1440*.92/r.w,900*.88/r.h);camTo(r.cx,r.cy,Math.max(1,s),dval||900)}
  
  async function main(){
    await new Promise(function(r){ifr.onload=r;ifr.srcdoc=html});
    try{await ifr.contentDocument.fonts.ready}catch(e){}
    await sleep(600);
    
    var w = ifr.contentWindow;
    var d = ifr.contentDocument;
    
    async function runAnim(){
      unglow();hist=[];C={x:720,y:450,s:1};T={x:730,y:452,s:1.03};V={x:0,y:0,s:0};ST=1.2;P.x=1500;P.y=260;
      heroVeil(true);
      if(window.__again)showHero('One dashboard.<br><em>Every channel.</em>','Orders, inventory, shipping & returns — in one engine','open');
      await rsleep(window.__again?4200:3600);window.__again=1;hideHero();heroVeil(false);await sleep(800);
      cur.style.opacity=1;
      var nav=d.querySelector('a[data-page="shipping"]'),nr=R(nav);
      focus(nr.cx+40,nr.cy,300,110,1000,2);
      await moveTo(nr.l+75,nr.cy,900);
      glow(nav,'dark',2);await sleep(380);
      await click(nav);setCap('Track every shipment','Across all couriers & marketplaces');
      veilOn(true);camTo(760,440,1.12,900);
      await waitFor(function(){return d.querySelector('.ship-table tbody tr')});
      await sleep(120);veilOn(false);unglow();
      await sleep(200);
      var pill=byText(d,'.ship-pill','🚚'),pr=R(pill);
      focus(pr.cx+60,pr.cy,420,80,900);
      await aimAt(pill,'light',650,0,0,2);await sleep(380);unglow();
      var rows=d.querySelectorAll('.ship-table tbody tr'),row=rows[1]||rows[0],cb=row.querySelector('input[type=checkbox]'),rr=R(row);
      focus(rr.l+300,rr.cy,640,130,950);
      await moveTo(R(cb).cx,R(cb).cy,650);glow(cb,'light',5);await sleep(150);
      await click(cb);await sleep(320);unglow();
      var cell=row.children[1];
      await moveTo(R(cell).l+90,R(cell).cy,380);glow(row,'light',0);await sleep(200);
      await click(row);
      await waitFor(function(){return d.querySelector('.ship-drawer')});
      unglow();
      var dr=R(d.querySelector('.ship-drawer'));
      focus(dr.cx,170+200,dr.w,300,1000,1.9);
      await sleep(600);
      var labs=d.querySelectorAll('.info-item'),cou=null;
      for(var i=0;i<labs.length;i++){if(labs[i].textContent.indexOf('Courier')===0){cou=labs[i];break}}
      if(cou){var cr=R(cou);focus(dr.cx,cr.cy,dr.w,170,900,2.1);await aimAt(cou,'light',600,-20,0,4);await sleep(450);unglow()}
      var tabs=d.querySelector('.ship-drawer-tabs'),tl=byText(tabs,'*','timeline');
      if(tl){var tr=R(tl);focus(dr.cx,tr.cy+110,dr.w,300,800,1.9);await aimAt(tl,'light',500,0,0,2);await sleep(150);await click(tl);await sleep(750);
        var ov=byText(d.querySelector('.ship-drawer-tabs'),'*','overview');
        await moveTo(R(ov).cx,R(ov).cy,420);await click(ov);unglow();await sleep(350)}
      var hold=byText(d.querySelector('.ship-drawer'),'button','put on hold'),hr=R(hold);
      focus(dr.cx,hr.cy,dr.w,190,950,2.1);
      await sleep(250);
      await aimAt(hold,'light',700,0,0,2);await sleep(300);
      setCap('Update in one click','Status, courier, notes — all in the drawer');
      await click(hold);w.showToast('Shipment updated');
      var toast=d.getElementById('toast');
      await sleep(250);var tr2=R(toast);focus(tr2.cx,tr2.cy-60,520,260,800,1.7);
      await sleep(1000);unglow();
      var x=byText(d.querySelector('.ship-drawer-head'),'button','✕');
      wide(1300);
      await aimAt(x,'light',650,0,0,2);await sleep(200);
      await click(x);unglow();
      var pid=null;
      var pn=d.querySelector('a[data-page="process"]'),pnr=R(pn);
      focus(pnr.cx+40,pnr.cy,300,110,900,2);
      await moveTo(pnr.l+75,pnr.cy,900);glow(pn,'dark',2);await sleep(300);
      await click(pn);unglow();
      setCap('Process orders','One queue for every channel',0);
      veilOn(true);camTo(760,440,1.1,800);
      var row2=await waitFor(function(){var l=d.querySelectorAll('.panel table tbody tr');for(var i=0;i<l.length;i++){if(l[i].textContent.indexOf('Validated')>-1&&l[i].querySelector('button'))return l[i]}});
      await sleep(120);veilOn(false);await sleep(250);
      setCap('Pick any order','Amazon, Flipkart, Meesho, Myntra & more',1);
      pid=row2.children[0].textContent.trim();
      var b1=row2.querySelector('button');
      fitEl(row2,950,1.45);
      await sleep(300);
      await aimAt(b1,'light',750,0,0,3);await sleep(300);
      await click(b1);unglow();
      var sp=await waitFor(function(){return byText(d,'button','start processing')});
      await sleep(300);
      setCap('Validate stock & pack','Scan items, generate the label',2);
      fitEl(d.querySelector('.step-card'),900,1.5);
      await sleep(350);
      await aimAt(sp,'light',750,0,0,3);await sleep(300);
      await click(sp);unglow();
      for(var k=1;k<=4;k++){
        var fb=await waitFor(function(){return d.querySelector('.step-footer .btn.primary')});
        await sleep(380);
        if(k===4)setCap('Dispatch to courier','One confirmation — handed over',3);
        fitEl(d.querySelector('.step-card'),800,1.7);
        fb=d.querySelector('.step-footer .btn.primary');
        await aimAt(fb,'light',k===1?650:450,0,0,3);await sleep(k===4?420:240);
        await click(fb);unglow();
      }
      var sb=await waitFor(function(){return d.querySelector('.success-block')});
      await sleep(200);fitEl(sb,1000,1.5);
      await sleep(1500);
      hideCap();wide(1300);
      await moveTo(1050,640,800);cur.style.opacity=0;await sleep(600);
      heroVeil(true);showHero('Orders processed in <em>3 easy steps</em>','All channels. One dashboard.','end');
      await rsleep(3800);
      try{w.eval("(function(){var o=ORDERS.find(function(x){return x.id==='"+pid+"'});if(o){o.stage=0;o.singleStep=0}state.procSelectedOrderId=null;})()")}catch(e){}
      w.shipState.activeTab='all';w.shipState.drawer=null;
      d.querySelector('a[data-page="dashboard"]').click();
      await sleep(250);hideHero();await sleep(500);
    }
    
    for(;;){
      try{await runAnim()}catch(e){console.error(e);await sleep(1200);try{w.shipState.drawer=null}catch(_){}}
    }
  }
  main();
})();
